//! Certificate authorities and keys `rcgen`'s ring backend cannot make.
//!
//! Each value is DER, Base64, with no PEM armor; the keys are PKCS#8. They
//! were generated by OpenSSL 3.2.4 (the phase 4 / M2a plan's P6, and the
//! execution record row about how the keys were converted): `rcgen` can sign
//! with an RSA key but cannot generate one, and it can neither sign with a
//! P-521 key nor take an EC PKCS#8 key that leaves its public key out.
//!
//! Every CA is valid from 2026-10-30 02:38:57 UTC to 2036-10-27 02:38:57 UTC,
//! so the cases that use them pin the clock at 2027-01-01T00:00:00Z (P7).
//! Each CA carries a critical `basicConstraints CA:TRUE`, a critical
//! `keyUsage keyCertSign, cRLSign` and a subject key identifier, and pairs
//! with its own key.

/// An RSA 2048-bit private key (1216 bytes): ring signs with it but cannot
/// generate one, so a case makes an RSA CA self-signed with it.
pub(crate) const RSA_2048_KEY: &str = "";

/// A P-521 CA, `CN=rurge test P-521 CA`: ring cannot sign with P-521 (P5
/// item 11).
pub(crate) const P521_CA: &str = "";

/// The private key of `P521_CA` (241 bytes).
pub(crate) const P521_KEY: &str = "";

/// A P-256 CA, `CN=rurge test no-public-key CA`: its PKCS#8 key leaves the
/// inner `ECPrivateKey`'s `[1]` public key out, which ring requires (P5
/// item 11).
pub(crate) const NO_PUBLIC_CA: &str = "";

/// The private key of `NO_PUBLIC_CA` (67 bytes).
pub(crate) const NO_PUBLIC_KEY: &str =
    "MEECAQAwEwYHKoZIzj0CAQYIKoZIzj0DAQcEJzAlAgEBBCAFeoHPREToOFN6fn9HGfBsYthz+1vCvgaQQNiy2k4FLQ==";

/// A P-256 CA whose subject is two attributes in one RDN (`O=rurge+CN=multi`):
/// rcgen's `DistinguishedName::from_name` refuses it (P5 item 12).
pub(crate) const MULTI_RDN_CA: &str = "";

/// The private key of `MULTI_RDN_CA` (138 bytes).
pub(crate) const MULTI_RDN_KEY: &str = "MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQghSTrUSgnB7bhP3M6O3hvVup3oMIWS0hNVyatnxIMMWShRANCAAQUqn/T7DD3TvyZyy650B42Vd/TifW1ahYcGzbH5j160Yrxkoslt+axtIxbhJTEiVt2YIqlTm1fMBJ6bNF8jKN3";

/// A P-256 CA whose subject has one attribute type twice (`OU=a, OU=b,
/// CN=dup`): rcgen merges them, so the issuer it rebuilds differs from the
/// subject (P5 item 13).
pub(crate) const DUP_ATTR_CA: &str = "";

/// The private key of `DUP_ATTR_CA` (138 bytes).
pub(crate) const DUP_ATTR_KEY: &str = "MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgO6aIBPhNOwPznypO8EaEoYS227/aKSUyC/iEN5pVz0ehRANCAASOhzyvMvBKgI9xhE7AxuavjtyyBQck7ttzWQdwSM/i/pR/DA/EUb8jtBpoJz3oTGufVdxZIRJtJpI57C245BBw";
